"""Two-field desktop setup. No backend events are generated by this tool."""
import hashlib
import json
import os
import re
import subprocess
import sys
import threading
import time
import webbrowser
from datetime import datetime
from contextlib import contextmanager
from pathlib import Path
from urllib.parse import urlparse

import requests

from check_connection import check
from connection import resolve

HERE = Path(__file__).resolve().parent
CONFIG = HERE / 'runtime' / 'web-connection.json'
LOCAL = 'http://127.0.0.1:9000'
SERVICE = 'parkingmate-field-monitor-v1'


def validate_settings(api, key):
    api, key = api.strip(), key.strip()
    if not api or not key:
        raise ValueError('서버 주소와 센서 키를 모두 입력하세요.')
    # Nonexistent default config prevents old local settings from filling blanks.
    api, key = resolve(api, key, config_path=None)
    host = urlparse(api).hostname
    if not api.startswith('https://') and host not in ('localhost', '127.0.0.1', '::1'):
        raise ValueError('배포 서버 주소는 https://로 입력하세요.')
    return api, key


def forwarding_folder(api):
    # Stable per-server history retains pending records and source-ID deduplication.
    return HERE / 'web-runtime' / hashlib.sha256(api.encode()).hexdigest()[:24]


def save_settings(api, key):
    CONFIG.parent.mkdir(parents=True, exist_ok=True)
    temporary = CONFIG.with_suffix('.json.tmp')
    temporary.write_text(json.dumps({'api': api, 'sensor_key': key}, ensure_ascii=False), encoding='utf-8')
    temporary.replace(CONFIG)


def local_state():
    try:
        response = requests.get(LOCAL + '/api/monitor', timeout=2)
        response.raise_for_status()
        state = response.json()
        if state.get('service') != SERVICE:
            raise RuntimeError('9000 포트를 다른 프로그램이 사용 중이에요.')
        return state
    except requests.ConnectionError:
        return None
    except (requests.RequestException, ValueError) as error:
        raise RuntimeError('9000 포트의 수신 프로그램을 확인할 수 없어요. 다른 프로그램이 실행 중인지 확인하세요.') from error


def stop_local(state):
    if not state:
        return
    page = requests.get(LOCAL + '/', timeout=3)
    page.raise_for_status()
    match = re.search(r"const actionToken='([a-f0-9]+)'", page.text)
    if not match:
        raise RuntimeError('현재 수신 프로그램을 안전하게 종료할 수 없어요.')
    response = requests.post(LOCAL + '/api/stop', headers={'X-Field-Token': match[1]}, timeout=3)
    response.raise_for_status()
    for _ in range(80):
        time.sleep(0.25)
        if local_state() is None:
            return
    raise RuntimeError('수신 프로그램 종료를 기다리는 중이에요. 잠시 후 다시 눌러주세요.')


@contextmanager
def setup_lock():
    CONFIG.parent.mkdir(parents=True, exist_ok=True)
    with (CONFIG.parent / 'web-setup.lock').open('a+b') as handle:
        handle.seek(0, 2)
        if handle.tell() == 0:
            handle.write(b'0'); handle.flush()
        handle.seek(0)
        try:
            if os.name == 'nt':
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as error:
            raise RuntimeError('다른 설정 창에서 연결 중이에요. 잠시 후 다시 눌러주세요.') from error
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == 'nt':
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def start_forwarding(api, key, report=lambda text: None):
    with setup_lock():
        return _start_forwarding(api, key, report)


def _start_forwarding(api, key, report):
    # Check an empty batch before replacing the currently running capture service.
    report('서버 주소와 센서 키를 확인하는 중이에요. 잠시 기다려주세요.')
    result = check(api, key)
    state = local_state()
    saved = {}
    if CONFIG.exists():
        saved = json.loads(CONFIG.read_text(encoding='utf-8-sig'))
    if (state and state.get('mode') == 'forwarding' and state.get('api') == api
            and saved.get('api') == api and saved.get('sensor_key') == key):
        return result
    report('서버 확인 완료. 수신 프로그램을 웹 전송 모드로 바꾸는 중이에요.')
    stop_local(state)
    save_settings(api, key)
    folder = forwarding_folder(api)
    folder.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    python = Path(sys.executable).with_name('python.exe') if os.name == 'nt' else Path(sys.executable)
    if not python.exists():
        python = Path(sys.executable)
    command = [str(python), '-u', str(HERE / 'field_monitor.py'), '--forward',
               '--config', str(CONFIG), '--state-dir', str(folder), '--serial', 'auto']
    # The key is in a private file, never command-line arguments or log messages.
    with (folder / (stamp + '.log')).open('w', encoding='utf-8') as output, \
            (folder / (stamp + '.error.log')).open('w', encoding='utf-8') as errors:
        process = subprocess.Popen(command, cwd=HERE, stdout=output, stderr=errors,
                                   creationflags=subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0)
    for _ in range(60):
        time.sleep(0.25)
        state = local_state()
        if state and state.get('mode') == 'forwarding' and state.get('api') == api:
            return result
        if process.poll() is not None:
            break
    raise RuntimeError('수신 프로그램을 시작하지 못했어요. sensor/web-runtime의 최신 error.log를 확인하세요.')


def friendly_error(error):
    # Never display the key or raw server response, even if a server echoes it.
    if isinstance(error, requests.Timeout):
        return '서버 응답이 늦어요. 인터넷과 서버 실행 상태를 확인한 뒤 다시 눌러주세요.'
    if isinstance(error, requests.HTTPError):
        status = error.response.status_code if error.response is not None else '?'
        return f'서버 확인 실패 (HTTP {status}). 서버 주소·센서 키·wirari 등록을 웹 담당자에게 확인해 주세요.'
    if isinstance(error, requests.RequestException):
        return '서버에 연결하지 못했어요. 인터넷과 서버 주소를 확인해 주세요.'
    if isinstance(error, RuntimeError):
        return str(error)
    if isinstance(error, ValueError):
        return '설정 또는 서버 형식이 맞지 않아요. https://서버주소 형태(/api 제외), 센서 키, wirari 센서 활성화를 확인하세요.'
    return '시작하지 못했어요. 수신 프로그램과 저장 폴더 상태를 확인해 주세요.'


def main():
    import tkinter as tk
    from tkinter import ttk

    root = tk.Tk()
    root.title('ParkingMate 웹 연결')
    root.geometry('720x650')
    root.minsize(660, 650)
    root.configure(background='#f4f6f8')
    style = ttk.Style(root)
    style.theme_use('clam')
    style.configure('TFrame', background='#f4f6f8')
    style.configure('TLabel', font=('맑은 고딕', 11), background='#f4f6f8', foreground='#17243a')
    style.configure('Title.TLabel', font=('맑은 고딕', 18, 'bold'))
    style.configure('TButton', font=('맑은 고딕', 11), padding=10)
    style.configure('TEntry', padding=8)
    frame = ttk.Frame(root, padding=28)
    frame.pack(fill='both', expand=True)
    ttk.Label(frame, text='센서를 배포된 웹에 연결', style='Title.TLabel').pack(anchor='w')
    ttk.Label(frame, text='웹 담당자에게 받은 서버 주소와 센서 키를 입력하세요.').pack(anchor='w', pady=(7, 20))
    ttk.Label(frame, text='백엔드 서버 주소 · /api 제외').pack(anchor='w')
    api = tk.StringVar()
    key = tk.StringVar()
    api_entry = ttk.Entry(frame, textvariable=api, font=('맑은 고딕', 11))
    api_entry.pack(fill='x', pady=(5, 14))
    ttk.Label(frame, text='센서 키 · SENSOR_KEY').pack(anchor='w')
    key_entry = ttk.Entry(frame, textvariable=key, show='●', font=('맑은 고딕', 11))
    key_entry.pack(fill='x', pady=(5, 7))
    show_key = tk.BooleanVar(value=False)
    ttk.Checkbutton(frame, text='키 표시', variable=show_key,
                    command=lambda: key_entry.configure(show='' if show_key.get() else '●')).pack(anchor='w')
    ttk.Label(frame, text='인터넷·STM32 USB·Pico 핫스팟 연결 후 사용하세요.\n연결 전에는 센서 통과를 잠시 멈춰주세요.\n연결 후 받은 통과와 같은 서버의 미전송 기록을 서버로 보냅니다.',
              wraplength=610).pack(anchor='w', pady=(14, 15))
    status = tk.StringVar(value='기존 현장 테스트 기록은 별도로 보관됩니다.')
    ttk.Label(frame, textvariable=status, wraplength=610).pack(anchor='w', pady=(0, 12))
    button = ttk.Button(frame, text='연결 확인 후 시작')
    button.pack(fill='x')
    messages = __import__('queue').Queue()
    busy = False

    def begin():
        nonlocal busy
        if busy:
            return
        try:
            endpoint, secret = validate_settings(api.get(), key.get())
        except Exception as error:
            status.set(friendly_error(error))
            return
        busy = True
        button.configure(state='disabled')
        api_entry.configure(state='disabled')
        key_entry.configure(state='disabled')
        def work():
            try:
                # Reuse the existing hotspot settings; failures remain visible in the dashboard.
                if os.name == 'nt':
                    messages.put(('status', 'Pico 핫스팟을 준비하는 중이에요.'))
                    try:
                        subprocess.run(['powershell.exe', '-NoProfile', '-ExecutionPolicy', 'Bypass',
                                        '-File', str(HERE / 'ensure-field-hotspot.ps1')],
                                       capture_output=True, timeout=45, creationflags=subprocess.CREATE_NO_WINDOW)
                    except (OSError, subprocess.TimeoutExpired):
                        pass
                start_forwarding(endpoint, secret, lambda text: messages.put(('status', text)))
                messages.put(('success', '서버 인증 확인 · 웹 전송을 시작했어요. 카운터에서 보드 연결과 전송 완료를 확인하세요.'))
            except Exception as error:
                messages.put(('error', friendly_error(error)))
        threading.Thread(target=work, daemon=True).start()

    def poll():
        nonlocal busy
        while not messages.empty():
            kind, message = messages.get()
            status.set(message)
            if kind in ('success', 'error'):
                busy = False
                button.configure(state='normal')
                api_entry.configure(state='normal')
                key_entry.configure(state='normal')
                if kind == 'success':
                    button.configure(text='다시 확인 / 카운터 열기')
                    webbrowser.open(LOCAL + '/')
        root.after(150, poll)

    def close():
        if busy:
            status.set('연결 작업이 끝난 뒤 창을 닫아주세요.')
        else:
            root.destroy()

    root.protocol('WM_DELETE_WINDOW', close)
    button.configure(command=begin)
    if CONFIG.exists():
        try:
            saved = json.loads(CONFIG.read_text(encoding='utf-8-sig'))
            api.set(saved.get('api', ''))
            key.set(saved.get('sensor_key', ''))
            status.set('저장된 설정을 불러왔어요. 버튼을 누르면 다시 확인하고 연결합니다.')
        except (OSError, ValueError):
            status.set('저장된 설정을 읽지 못했어요. 두 값을 다시 입력하세요.')
    api_entry.focus_set()
    root.update_idletasks()
    required_height = max(650, frame.winfo_reqheight())
    root.minsize(660, required_height)
    root.geometry('720x' + str(required_height))
    if '--layout-check' in sys.argv:
        root.update()
        visible = bool(button.winfo_ismapped()) and button.winfo_y() + button.winfo_height() <= frame.winfo_height()
        print(json.dumps({'button_visible': visible, 'width': root.winfo_width(),
                          'height': root.winfo_height(), 'frame_height': frame.winfo_height(),
                          'button_bottom': button.winfo_y() + button.winfo_height(), 'fields': 2}))
        assert visible
        root.destroy()
        return
    root.after(150, poll)
    root.mainloop()


if __name__ == '__main__':
    main()
